def normalize_vector(vector: list[float]) -> list[float]:
    if not vector or len(vector) == 0:
        return []

    l2_norm = 0.0
    for v in vector:
        l2_norm += math.pow(v, 2)

    if l2_norm > 0:
        return [v / l2_norm for v in vector]
    else:
        return vector
