fn read_dir(path: &str) -> Result<Vec<PathBuf>, > {
    let archives = fs::read_dir(path)?;

    let mut files = vec![];

    for Ok(file) in archives {
        if file.file_type().unwrap().is_dir() {
            files.append(&mut read_dir(file.path().to_str().unwrap()))
        } else {
            files.push(file.path())
        }
    }

    files
}
